    "id": "amc8-2017-12",
    "title": "2017 AMC 8 Problem 12: Remainder One",
    "sourceType": "AMC",
    "contest": "AMC 8",
    "year": 2017,
    "problemNumber": 12,
    "category": "Number Theory",
    "subcategory": "LCM",
    "difficulty": 2,
    "statement": "The smallest positive integer greater than 1 that leaves a remainder of 1 when divided by 4, 5, and 6 lies between which of the following pairs of numbers?",
    "choices": [
      {
        "label": "A",
        "text": "2 and 19"
      },
      {
        "label": "B",
        "text": "20 and 39"
      },
      {
        "label": "C",
        "text": "40 and 59"
      },
      {
        "label": "D",
        "text": "60 and 79"
      },
      {
        "label": "E",
        "text": "80 and 124"
      }
    ],
    "answer": "D",
    "shortAnswer": "60 and 79",
    "solutionSteps": [
      {
        "title": "Remove the shared remainder",
        "body": "If n leaves remainder 1 when divided by 4, 5, and 6, then n−1 is divisible by all three numbers."
      },
      {
        "title": "Find the common multiple",
        "body": "The least common multiple is LCM(4,5,6)=60."
      },
      {
        "title": "Add the remainder back",
        "body": "The smallest solution greater than 1 is 60+1=61, and it leaves remainder 1 for each divisor."
      },
      {
        "title": "Locate the range",
        "body": "61 lies between 60 and 79."
      }
    ],
    "animationFrames": [
      {
        "title": "Align remainders",
        "narration": "The three division rules all point to remainder 1.",
        "visualHint": "n−1 is shown as divisible by 4,5,6."
      },
      {
        "title": "Find LCM",
        "narration": "4, 5, and 6 combine into 60.",
        "visualHint": "LCM = 60 appears."
      },
      {
        "title": "Add one",
        "narration": "60 + 1 = 61.",
        "visualHint": "61 drops into the interval 60–79."
      }
    ],
    "animation": {
      "type": "remainder-one-interval",
      "data": {
        "divisors": [
          4,
          5,
          6
        ],
        "remainder": 1
      }
    },
