      { "title": "Count rows", "narration": "Hexagon 4 has rows: 4,5,6,7,6,5,4.", "visualHint": "Row counts listed." },
      { "title": "Sum", "narration": "4+5+6+7+6+5+4 = 37.", "visualHint": "Choice B circled." }
